// matematica.js
export const PI = 3.14159;

export function somar(a, b) {
  return a + b;
}

function subtrair(a, b) {
  return a - b;
}

// Também é válido agrupar os exports no final do ficheiro:
export { subtrair };

// calculadora.js
export default function calcular(operacao, a, b) {
  switch (operacao) {
    case "somar":
      return a + b;
    case "subtrair":
      return a - b;
    default:
      throw new Error(`Operação desconhecida: ${operacao}`);
  }
}

// principal.js
import calcular from "./calculadora.js";
// Podia igualmente chamar-se "import operar from ..." — o nome é livre.

console.log(calcular("somar", 4, 5));

