// texto.js
export function maiuscula(texto) {
  return texto.toUpperCase();
}

export function contarPalavras(texto) {
  return texto.trim().split(/\s+/).length;
}

// principal.js
import { maiuscula, contarPalavras } from "./texto.js";

const frase = "javascript é fantástico";

console.log(maiuscula(frase));
console.log(contarPalavras(frase));

// carrinho.js
export default function criarCarrinho() {
  return [];
}

export function adicionarItem(carrinho, item) {
  return [...carrinho, item];
}

export function calcularTotal(carrinho) {
  return carrinho.reduce((total, item) => total + item.preco, 0);
}

// principal.js
import novoCarrinho, { adicionarItem, calcularTotal as somarPrecos } from "./carrinho.js";

let carrinho = novoCarrinho();
carrinho = adicionarItem(carrinho, { nome: "Livro", preco: 15 });
carrinho = adicionarItem(carrinho, { nome: "Caneta", preco: 3 });

console.log(somarPrecos(carrinho));

// relatorioSimples.js
export default function gerar(dados) {
  return `Total de itens: ${dados.length}`;
}

// relatorioDetalhado.js
export default function gerar(dados) {
  const soma = dados.reduce((total, valor) => total + valor, 0);
  return `Total de itens: ${dados.length} | Soma dos valores: ${soma}`;
}

// principal.js
async function mostrarRelatorio(dados, detalhado) {
  const caminho = detalhado ? "./relatorioDetalhado.js" : "./relatorioSimples.js";
  const { default: gerar } = await import(caminho);
  console.log(gerar(dados));
}

// Só carrega o código do relatório detalhado quando é mesmo preciso,
// reduzindo o tamanho do código carregado inicialmente (code-splitting).
mostrarRelatorio([10, 20, 30], true);
